    <div id="skillContent"></div>
    <textarea id="skillRawData" style="display:none;">$1</textarea>

    <div class="seal-decoration"></div>
    <div class="scroll-bottom-ornament"></div>
</div>

<script>
(function(){
    function escapeHtml(t){ if(!t) return ''; var d = document.createElement('div'); d.textContent = t; return d.innerHTML; }

    function updateHeight(){ 
        setTimeout(function(){ 
            var h = document.body.scrollHeight; 
            if(window.parent && window.parent !== window) {
                window.parent.postMessage({type:'resizeIframe', height:h}, '*'); 
            }
        }, 50); 
    }

    function extractRawSkill(){
        var el = document.getElementById('skillRawData');
        return el ? (el.value || el.textContent || '').trim() : '';
    }

    function parseSkillContent(raw) {
        var result = {
            name: '',
            type: '',
            levelText: '',
            levelFrom: '',
            levelTo: '',
            stageFrom: '',
            stageTo: '',
            effects: [],
            acquire: '',
            insight: ''
        };

        if(!raw || !raw.trim()) return result;

        // 解析技能名称 - 支持多种格式
        var nameMatch = raw.match(/\*\*技能名称\*\*[：:]\s*([^\n]+)/i);
        if(nameMatch) result.name = nameMatch[1].trim();

        // 解析技能类型 - 支持主动/被动/天赋/特殊
        var typeMatch = raw.match(/\*\*技能类型\*\*[：:]\s*([^\n]+)/i);
        if(typeMatch) result.type = typeMatch[1].trim();

        // 解析等级/阶段 - 支持多种格式
        var levelMatch = raw.match(/\*\*(?:当前)?等级(?:\/阶段)?\*\*[：:]\s*([^\n]+)/i);
        if(levelMatch) {
            var levelText = levelMatch[1].trim();
            result.levelText = levelText;

            // 尝试解析 → 分隔的等级
            if(levelText.indexOf('→') !== -1) {
                var levelParts = levelText.split('→');
                if(levelParts.length === 2) {
                    var fromPart = levelParts[0].trim();
                    var toPart = levelParts[1].trim();

                    // 解析起始等级 - 支持 Lv 数字 (阶段) 或纯文本
                    var fromLvMatch = fromPart.match(/Lv\s*(\d+)\s*\(([^)]+)\)/i);
                    if(fromLvMatch) {
                        result.levelFrom = fromLvMatch[1];
                        result.stageFrom = fromLvMatch[2];
                    } else {
                        // 纯文本阶段如 "入门" → "精通"
                        result.stageFrom = fromPart;
                    }

                    // 解析目标等级
                    var toLvMatch = toPart.match(/Lv\s*(\d+)\s*\(([^)]+)\)/i);
                    if(toLvMatch) {
                        result.levelTo = toLvMatch[1];
                        result.stageTo = toLvMatch[2];
                    } else {
                        result.stageTo = toPart;
                    }
                }
            } else {
                // 单一等级
                var singleLvMatch = levelText.match(/Lv\s*(\d+)\s*\(([^)]+)\)/i);
                if(singleLvMatch) {
                    result.levelFrom = singleLvMatch[1];
                    result.stageFrom = singleLvMatch[2];
                } else {
                    // 纯文本阶段
                    result.stageFrom = levelText;
                }
            }
        }

        // 解析效果描述 - 支持多种格式
        var effectSection = raw.match(/\*\*效果描述[^\n]*\*\*[：:]?\n([\s\S]*?)(?=\n\s*(?:\*\s*)?\*\*(?:习得|提升方式|习得\/提升方式|角色感悟|表现|角色感悟\/表现)|$)/i);
        if(effectSection) {
            var effectText = effectSection[1];

            // 解析主要效果 - 支持 **主要效果**: 或 **[主要效果]**:
            var mainEffect = effectText.match(/\*\*\[?主要效果\]?\*\*[：:]\s*([^\n]+)/i);
            if(mainEffect) {
                result.effects.push({ label: '主要效果', icon: '⚔️', content: mainEffect[1].trim() });
            }

            // 解析附加效果/变化
            var addEffect = effectText.match(/\*\*\[?(?:附加效果|变化)\]?\*\*[：:]\s*([^\n]+)/i);
            if(addEffect) {
                result.effects.push({ label: '附加效果', icon: '✨', content: addEffect[1].trim() });
            }

            // 解析限制/代价
            var limitEffect = effectText.match(/\*\*\[?(?:限制|代价)\]?\*\*[：:]\s*([^\n]+)/i);
            if(limitEffect) {
                result.effects.push({ label: '限制/代价', icon: '⚠️', content: limitEffect[1].trim() });
            }

            // 如果没有匹配到任何效果，尝试通用匹配
            if(result.effects.length === 0) {
                var generalEffects = effectText.matchAll(/\*\*\[?([^\]*\]]+)\]?\*\*[：:]\s*([^\n]+)/gi);
                var ge = generalEffects.next();
                while(!ge.done) {
                    var label = ge.value[1].trim();
                    var content = ge.value[2].trim();
                    var icon = '📋';
                    if(label.indexOf('主要') !== -1) icon = '⚔️';
                    else if(label.indexOf('附加') !== -1 || label.indexOf('变化') !== -1) icon = '✨';
                    else if(label.indexOf('限制') !== -1 || label.indexOf('代价') !== -1) icon = '⚠️';
                    result.effects.push({ label: label, icon: icon, content: content });
                    ge = generalEffects.next();
                }
            }
        }

        // 解析习得/提升方式
        var acquireMatch = raw.match(/\*\*(?:习得|提升方式|习得\/提升方式)\*\*[：:]\s*([^\n]+)/i);
        if(acquireMatch) result.acquire = acquireMatch[1].trim();

        // 解析角色感悟/表现
        var insightMatch = raw.match(/\*\*(?:角色感悟|表现|角色感悟\/表现)\*\*[：:]\s*([^\n]+)/i);
        if(insightMatch) result.insight = insightMatch[1].trim();

        return result;
    }

    function getTypeClass(type) {
        if(!type) return 'active';
        var t = type.toLowerCase();
        if(t.indexOf('被动') !== -1) return 'passive';
        if(t.indexOf('天赋') !== -1) return 'talent';
        if(t.indexOf('特殊') !== -1) return 'special';
        if(t.indexOf('终极') !== -1 || t.indexOf('大招') !== -1) return 'special';
        return 'active';
    }

    function getSkillIcon(type) {
        if(!type) return '⚔️';
        var t = type.toLowerCase();
        if(t.indexOf('被动') !== -1) return '🛡️';
        if(t.indexOf('天赋') !== -1) return '⭐';
        if(t.indexOf('特殊') !== -1) return '🌟';
        if(t.indexOf('终极') !== -1 || t.indexOf('大招') !== -1) return '💥';
        if(t.indexOf('辅助') !== -1) return '💚';
        if(t.indexOf('控制') !== -1) return '🌀';
        return '⚔️';
    }

    function renderSkill(data) {
        if(!data.name) return '<div class="empty-state">等待技能数据...</div>';

        var html = '<div class="skill-header">';
        html += '<div class="skill-icon">' + getSkillIcon(data.type) + '</div>';
        html += '<div class="skill-name">' + escapeHtml(data.name) + '</div>';
        if(data.type) html += '<span class="skill-type-badge ' + getTypeClass(data.type) + '">' + escapeHtml(data.type) + '</span>';
        html += '</div>';

        // 等级显示
        if(data.levelFrom || data.levelTo || data.stageFrom || data.stageTo) {
            html += '<div class="skill-level-section"><div class="skill-level-label">等级/阶段</div><div class="skill-level-display">';

            if(data.levelFrom || data.stageFrom) {
                html += '<div class="level-from">';
                if(data.levelFrom) html += '<span class="level-value">Lv ' + escapeHtml(data.levelFrom) + '</span>';
                if(data.stageFrom) html += '<span class="level-stage">' + escapeHtml(data.stageFrom) + '</span>';
                html += '</div>';
            }

            if(data.levelTo || data.stageTo) {
                html += '<span class="level-arrow">→</span>';
                html += '<div class="level-to">';
                if(data.levelTo) html += '<span class="level-value">Lv ' + escapeHtml(data.levelTo) + '</span>';
                if(data.stageTo) html += '<span class="level-stage">' + escapeHtml(data.stageTo) + '</span>';
                html += '</div>';
            }

            html += '</div></div>';
        }

        // 效果描述
        if(data.effects.length > 0) {
            html += '<div class="effect-section"><div class="section-title">效果描述</div>';
            data.effects.forEach(function(effect) {
                html += '<div class="effect-card"><div class="effect-label">' + effect.icon + ' ' + escapeHtml(effect.label) + '</div>';
                html += '<div class="effect-content">' + escapeHtml(effect.content) + '</div></div>';
            });
            html += '</div>';
        }

        // 习得方式
        if(data.acquire) {
            html += '<div class="acquire-section"><div class="section-title">习得方式</div>';
            html += '<div class="acquire-content">' + escapeHtml(data.acquire) + '</div></div>';
        }

        // 角色感悟
        if(data.insight) {
            html += '<div class="insight-section"><div class="section-title">角色感悟</div>';
            html += '<div class="insight-content">' + escapeHtml(data.insight) + '</div></div>';
        }

        return html;
    }

    function initSkill() {
        var container = document.getElementById('skillContent');
        var raw = extractRawSkill();

        if(!raw || !raw.trim()) {
            container.innerHTML = '<div class="empty-state">等待技能数据...</div>';
            return;
        }

        var parsed = parseSkillContent(raw);
        container.innerHTML = renderSkill(parsed);
        updateHeight();
    }

    if(document.readyState === 'complete' || document.readyState === 'interactive') setTimeout(initSkill, 0);
    document.addEventListener('DOMContentLoaded', initSkill);
    setTimeout(initSkill, 100);
    setTimeout(initSkill, 300);
})();
</script>
</body>
</html>
